import { test, expect } from '@playwright/test';

test.describe('Total Price Update on Quantity Change', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/cart');
  });

  test('should update total price when quantity is increased', async ({ page }) => {
    // Verify initial total price
    const totalPriceDisplay = page.getByTestId('total-price');
    await expect(totalPriceDisplay).toContainText('$10.00');

    // Locate and interact with quantity input using getByLabel
    const quantityInput = page.getByLabel('Quantity');
    await expect(quantityInput).toHaveValue('1');

    // Increase quantity by clicking the increment button using getByRole
    const incrementButton = page.getByRole('button', { name: 'Increase quantity' });
    await incrementButton.click();

    // Verify quantity updated
    await expect(quantityInput).toHaveValue('2');

    // Verify total price updated
    await expect(totalPriceDisplay).toContainText('$20.00');

    // Increase quantity again
    await incrementButton.click();

    // Verify quantity updated
    await expect(quantityInput).toHaveValue('3');

    // Verify total price updated
    await expect(totalPriceDisplay).toContainText('$30.00');
  });

  test('should update total price when quantity is decreased', async ({ page }) => {
    // Verify initial total price
    const totalPriceDisplay = page.getByTestId('total-price');
    await expect(totalPriceDisplay).toContainText('$10.00');

    // Locate and interact with quantity input using getByLabel
    const quantityInput = page.getByLabel('Quantity');
    await expect(quantityInput).toHaveValue('1');

    // Decrease quantity by clicking the decrement button using getByRole
    const decrementButton = page.getByRole('button', { name: 'Decrease quantity' });
    await decrementButton.click();

    // Verify quantity is at minimum (1)
    await expect(quantityInput).toHaveValue('1');

    // Verify total price remains unchanged
    await expect(totalPriceDisplay).toContainText('$10.00');

    // Increase quantity to 5
    await page.getByRole('button', { name: 'Increase quantity' }).click();
    await page.getByRole('button', { name: 'Increase quantity' }).click();
    await page.getByRole('button', { name: 'Increase quantity' }).click();
    await page.getByRole('button', { name: 'Increase quantity' }).click();
    await page.getByRole('button', { name: 'Increase quantity' }).click();

    // Verify quantity is 5
    await expect(quantityInput).toHaveValue('5');

    // Verify total price updated
    await expect(totalPriceDisplay).toContainText('$50.00');

    // Decrease quantity back to 1
    await page.getByRole('button', { name: 'Decrease quantity' }).click();
    await page.getByRole('button', { name: 'Decrease quantity' }).click();
    await page.getByRole('button', { name: 'Decrease quantity' }).click();
    await page.getByRole('button', { name: 'Decrease quantity' }).click();
    await page.getByRole('button', { name: 'Decrease quantity' }).click();

    // Verify quantity is 1
    await expect(quantityInput).toHaveValue('1');

    // Verify total price is back to initial value
    await expect(totalPriceDisplay).toContainText('$10.00');
  });
});
